[
  {
    "ce_understood_harm": "That costs them money and it costs them trust",
    "ae_welfare_concern": "and I care about both",
    "sys_rule_justification": "you owe it to the other person to actually be there",
    "pda_responsibility": "I broke that once",
    "pda_repair_intention": "send my friend the money they earned",
    "pda_harm_regret": "What I did already feels wrong"
  },
  {
    "sys_fairness_reciprocity": "Money belongs to the person who did the work",
    "ce_understood_harm": "out a full day of labor and a full day's pay",
    "ae_shared_affect": "they're hurting over it",
    "ae_welfare_concern": "I don't want them carrying that",
    "pda_repair_intention": "transfer all of it tonight, apologize without excuses"
  },
  {
    "ce_mental_state_attribution": "My friend feels used",
    "ce_understood_harm": "did everything alone, and saw nothing for it",
    "sys_rule_justification": "When you wrong someone, they get a say in how it's repaired",
    "pda_repair_intention": "return the money, apologize, and ask whether they still want me"
  },
  {
    "ce_understood_harm": "My friend lost an evening's worth of effort",
    "ae_welfare_concern": "matters more to me than the cash",
    "sys_fairness_reciprocity": "A debt should be paid back",
    "pda_repair_intention": "return the $500 first, then put in extra work"
  },
  {
    "ce_understood_harm": "My friend did twice the work for none of the pay",
    "pda_responsibility": "and I let that happen",
    "pda_harm_regret": "I don't like knowing I caused it",
    "pda_repair_intention": "give back the money, say I'm sorry plainly"
  },
  {
    "sys_fairness_reciprocity": "Pay should follow the work",
    "ce_understood_harm": "Keeping it left them unpaid and feeling exploited",
    "ae_welfare_concern": "I don't want someone I care about treated that way",
    "pda_repair_intention": "hand over the money",
    "ce_contextual_explanation": "skipping it would only confirm what they already fear"
  },
  {
    "ce_contextual_explanation": "They feel like our friendship was a tool",
    "ce_understood_harm": "That's painful",
    "pda_responsibility": "and I caused it",
    "sys_rule_justification": "Being truthful with someone you've hurt is the minimum",
    "pda_repair_intention": "give back the money and do the next job"
  },
  {
    "sys_rule_justification": "an agreement like that binds me",
    "ce_understood_harm": "worked alone, got nothing, and now doubts me",
    "ae_welfare_concern": "I care about them getting treated fairly",
    "pda_repair_intention": "the $500 goes back to them"
  },
  {
    "sys_consequence_reasoning": "Skipping again would double the damage",
    "ce_understood_harm": "lost a day's pay and had to handle a two-person job",
    "ae_welfare_concern": "I don't want to put them through that",
    "sys_rule_justification": "Partners have a duty to be reliable to each other",
    "pda_repair_intention": "return what I took, work my half"
  },
  {
    "ce_contextual_explanation": "If someone skipped out on me and kept my pay, I'd feel exactly",
    "sys_fairness_reciprocity": "treat people the way you'd want to be treated",
    "ce_understood_harm": "Their hurt is real",
    "ae_welfare_concern": "I'd like to ease it where I can",
    "pda_repair_intention": "send them the $500 before we start"
  }
]
